const path = require('path');
const express = require('express');
const routes = require('./routes/index');

const app = express();

app.engine('ejs', require('ejs-locals'));
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'ejs');
app.use(express.static(path.join(__dirname, 'public')));
app.use('/', routes);

module.exports = app;

#!/usr/bin/env node

const app = require('../app');
const http = require('http');

const port = normalizePort(process.env.PORT || '3000');
app.set('port', port);

const server = http.createServer(app);

server.listen(port);
server.on('error', onError);
server.on('listening', onListening);

function normalizePort(value) {
  const parsedPort = parseInt(value, 10);

  if (Number.isNaN(parsedPort)) {
    return value;
  }

  if (parsedPort >= 0) {
    return parsedPort;
  }

  return false;
}

function onError(error) {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const bind = typeof port === 'string' ? `Pipe ${port}` : `Port ${port}`;

  switch (error.code) {
    case 'EACCES':
      console.error(`${bind} requires elevated privileges`);
      process.exit(1);
      break;
    case 'EADDRINUSE':
      console.error(`${bind} is already in use`);
      process.exit(1);
      break;
    default:
      throw error;
  }
}

function onListening() {
  const address = server.address();
  const bind = typeof address === 'string' ? `pipe ${address}` : `port ${address.port}`;
  console.log(`Listening on ${bind}`);
}

const express = require('express');
const router = express.Router();

router.get('/', function(req, res) {
  res.render('index', {
    title: 'Видеокарта',
    pageTitle: 'Видеокарта',
    intro: 'Учебный сайт о видеокартах',
    navigation: [
      { href: '/', label: 'Главная' },
      { href: '/korzhik', label: 'Коржик' },
      { href: '/karamelka', label: 'Карамелька' },
      { href: '/kompot', label: 'Компот' }
    ]
  });
});

router.get('/korzhik', function(req, res) {
  res.render('cat', {
    title: 'Коржик',
    picture: '/images/korzhik.png',
    description: 'Средний котёнок в семье. Очень любит футбол, бегает, прыгает и весело исследует новые возможности.',
    navigation: [
      { href: '/', label: 'Главная' },
      { href: '/korzhik', label: 'Коржик' },
      { href: '/karamelka', label: 'Карамелька' },
      { href: '/kompot', label: 'Компот' }
    ]
  });
});

router.get('/karamelka', function(req, res) {
  res.render('cat', {
    title: 'Карамелька',
    picture: '/images/karamelka.jpeg',
    description: 'Самый младший член семьи. Уверенно ищет решения и любит яркие, красивые вещи.',
    navigation: [
      { href: '/', label: 'Главная' },
      { href: '/korzhik', label: 'Коржик' },
      { href: '/karamelka', label: 'Карамелька' },
      { href: '/kompot', label: 'Компот' }
    ]
  });
});

router.get('/kompot', function(req, res) {
  res.render('cat', {
    title: 'Компот',
    picture: '/images/kompot.png',
    description: 'Старший котёнок в семье. Любит логику, энциклопедии и спокойные, надёжные решения.',
    navigation: [
      { href: '/', label: 'Главная' },
      { href: '/korzhik', label: 'Коржик' },
      { href: '/karamelka', label: 'Карамелька' },
      { href: '/kompot', label: 'Компот' }
    ]
  });
});

module.exports = router;

body {
  margin: 0;
  font-family: Arial, sans-serif;
  background: #f5f7fb;
  color: #1f2937;
}

.site-header,
.site-footer {
  background: #0f172a;
  color: #fff;
  padding: 16px 24px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.site-brand {
  font-size: 1.2rem;
  font-weight: 700;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.site-nav a {
  color: #dbeafe;
  text-decoration: none;
}

.site-main {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 24px 48px;
}

.hero,
.card {
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
}

.hero {
  padding: 24px;
  margin-bottom: 24px;
}

.hero-content {
  display: grid;
  gap: 16px;
  grid-template-columns: minmax(0, 280px) 1fr;
  align-items: center;
}

.hero-content img {
  width: 100%;
  border-radius: 12px;
  object-fit: cover;
}

.card-grid {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.card {
  padding: 20px;
}

.site-footer {
  text-align: center;
}

@media (max-width: 640px) {
  .hero-content {
    grid-template-columns: 1fr;
  }
}
